update public.content set doc = jsonb_set(doc, '{resenas,0,texto_en}', to_jsonb('Victoria''s cabin is beautiful, exactly as it looks in the photos. The place is lovely — all you hear is the birds. We spent a long time watching different kinds of hummingbirds. It is perfect for resting and disconnecting, just what we were looking for. Victoria and her husband were very kind to us and made sure everything went well. Thank you so much for everything!'::text), true) where id = 'comercial' and coalesce(doc #>> '{resenas,0,texto_en}', '') = '';
update public.content set doc = jsonb_set(doc, '{resenas,1,texto_en}', to_jsonb('A fantastic place!! The house is incredibly beautiful and sits in a gorgeous natural setting with fantastic views. For us, as biologists interested in nature, it was wonderful to stay in the reserve this host couple created in the middle of Río Blanco. A very warm welcome, and they helped us book a guide for antpittas. Very good birdwatching. It may be the best place we have ever stayed. We highly recommend it to nature lovers who also want very comfortable accommodation.'::text), true) where id = 'comercial' and coalesce(doc #>> '{resenas,1,texto_en}', '') = '';
update public.content set doc = jsonb_set(doc, '{resenas,2,texto_en}', to_jsonb('I could not have dreamed of a better introduction to the Colombian countryside than landing at Cantares. It is an oasis: beautiful, peaceful, charming. The hosts Victoria and Jorge are generous and kind. The accommodation is very comfortable and the surroundings offer plenty of pleasant walks. I went there to watch birds and was not disappointed. Cantares and Río Blanco both, and areas a little further afield, offer opportunities for excellent birding.'::text), true) where id = 'comercial' and coalesce(doc #>> '{resenas,2,texto_en}', '') = '';
update public.content set doc = jsonb_set(doc, '{resenas,3,texto_en}', to_jsonb('For those of us looking to disconnect, the place is ideal. A wonderful spot.'::text), true) where id = 'comercial' and coalesce(doc #>> '{resenas,3,texto_en}', '') = '';
update public.content set doc = jsonb_set(doc, '{resenas,4,texto_en}', to_jsonb('Victoria was an excellent host; sharing a coffee with her while she told us about the reserve was very special. The cabin exceeded our expectations and the surroundings were incredible, including trails to different parts of the reserve. The diversity of birds, especially the hummingbirds, made the place all the more memorable. We will definitely be back; we felt at home and we loved it.'::text), true) where id = 'comercial' and coalesce(doc #>> '{resenas,4,texto_en}', '') = '';
update public.content set doc = jsonb_set(doc, '{resenas,5,texto_en}', to_jsonb('Victoria and Jorge are exceptional hosts, as is Carlos, who looks after the farm. Their cabin in the middle of a nature reserve is paradise. My partner and I spent four wonderful days enjoying the cabin, the birds, the hot tub and the rest. Beyond the lodging, the trails are wonderful for exploring and discovering the mountain. Absolutely recommended!'::text), true) where id = 'comercial' and coalesce(doc #>> '{resenas,5,texto_en}', '') = '';
update public.content set doc = jsonb_set(doc, '{resenas,6,texto_en}', to_jsonb('Victoria and her husband Jorge are excellent hosts, always attentive and helping us with whatever we needed. They arranged a birdwatching tour with a local guide and made us breakfast. The place is a dream, away from the city and surrounded by nature. The hot tub is wonderful for relaxing and unwinding at the end of the day. The cabin is beautiful, full of thoughtful touches and very well equipped. Very happy — we recommend this place wholeheartedly.'::text), true) where id = 'comercial' and coalesce(doc #>> '{resenas,6,texto_en}', '') = '';
update public.content set doc = jsonb_set(doc, '{resenas,7,texto_en}', to_jsonb('The place is spectacular, ideal for nature lovers; there are plenty of options for walking, but if you would rather rest, the cabin is cosy enough. The place is beautiful and the landscape incredible. I would go back a thousand times and I recommend it absolutely.'::text), true) where id = 'comercial' and coalesce(doc #>> '{resenas,7,texto_en}', '') = '';
update public.content set doc = jsonb_set(doc, '{resenas,8,texto_en}', to_jsonb('We spent two wonderful days at this reserve. Everything in the cabin was perfect and it was comfortable. Seeing birds and other animals was great. The hot tub worked perfectly. We enjoyed being able to talk with the hosts, and a HUGE thank you also to Carlos, who guided us and made our stay easy. The walks are great and enjoyable, and a setting like this in the mountains is unique. A real immersion in nature!'::text), true) where id = 'comercial' and coalesce(doc #>> '{resenas,8,texto_en}', '') = '';
update public.content set doc = jsonb_set(doc, '{resenas,9,texto_en}', to_jsonb('Our days at Reserva Cantares have been wonderful; the place is far better than any photo can convey. It is surrounded by nature, has stunning views of the snow-capped peaks, and the house has everything you need to cook, to unwind in the hot tub, to go looking for frogs with Mr Carlos, or to sit by the fireplace. Victoria and Jorge are exceptional hosts, very respectful and kind. They welcomed us with a coffee and were attentive to our questions. Carlos Ariel took us along the trails, which are very accessible. The best place we have stayed, and we will certainly return.'::text), true) where id = 'comercial' and coalesce(doc #>> '{resenas,9,texto_en}', '') = '';
update public.content set doc = jsonb_set(doc, '{resenas,10,texto_en}', to_jsonb('The cabin in the forest is a charming refuge, cosy and fully equipped, where everything works perfectly. Access is by a rural road in excellent condition. Victoria and Jorge, the hosts, are exceptional people, always attentive to their guests'' needs. The setting has well-designed and well-kept trails as well as waterfalls: an ideal place for birdwatching and bird photography. The morning views from bed, with the snow-capped peaks on the horizon, are incomparable. Highly recommended.'::text), true) where id = 'comercial' and coalesce(doc #>> '{resenas,10,texto_en}', '') = '';
update public.routes set scripts = jsonb_set(scripts, '{punto_3,en}', to_jsonb('This is the highest waterfall we have found so far in Cantares. We have built a small dam so you can come close and enjoy the water. If you wish, step in and feel its cold freshness falling over you: a simple and deeply revitalising experience.

This is also a good place to stop and watch how the forest captures and holds water. On the moss-covered walls of the waterfall we can see the process at work. Like a small natural sponge, the moss takes up and holds water from rain, mist and the humidity in the air, then releases it slowly. Like the bromeliads and other plants of the cloud forest, it helps keep the air humid and regulates the water moving through this ecosystem.'::text), true) where id = 'agua' and coalesce(scripts #>> '{punto_3,en}', '') = '';
update public.routes set scripts = jsonb_set(scripts, '{punto_6,en}', to_jsonb('Here you can pause, rest and enjoy this small natural stand of sietecueros, trees native to humid montane forest. Their canopy and the leaf litter that builds up on the ground help hold moisture and let water soak in. Their beautiful bloom, in violet and purple tones, fills the forest with colour and also draws a range of pollinators.'::text), true) where id = 'agua' and coalesce(scripts #>> '{punto_6,en}', '') = '';
update public.routes set scripts = jsonb_set(scripts, '{punto_12,en}', to_jsonb('The water we use day to day at the Reserve passes straight from the spring into a biofilter system, where it is cleaned by mechanical filtration.

The first tank receives the water coming from the spring. From there it passes to a second tank, where it rises slowly through a layer of medium-sized stone that traps the larger solid impurities. The water then reaches a third tank holding quarry sand. Here it filters downwards through the sand, which traps much finer particles.

Finally the water arrives at a fourth storage tank, from which it is distributed to the house and the cabin for everyday use.'::text), true) where id = 'agua' and coalesce(scripts #>> '{punto_12,en}', '') = '';
update public.routes set scripts = jsonb_set(scripts, '{arbol_1498,en}', to_jsonb('Tree ferns also play an important part in conserving water. Their large fronds capture moisture from the mist, and their trunks, often covered in mosses and other plants, help hold it. The water descends slowly to the ground, feeding soil moisture and infiltration. In this way these ferns form part of the forest''s complex network that captures, conserves and regulates water.'::text), true) where id = 'agua' and coalesce(scripts #>> '{arbol_1498,en}', '') = '';
update public.routes set scripts = jsonb_set(scripts, '{punto_mrjhynbt822,en}', to_jsonb('This is a good place to take a break.'::text), true) where id = 'agua' and coalesce(scripts #>> '{punto_mrjhynbt822,en}', '') = '';
update public.routes set scripts = jsonb_set(scripts, '{punto_mrji6sqk774,en}', to_jsonb('Río Blanco supplies roughly 35% of the water consumed by the city of Manizales. Although the springs and creeks of Cantares do not feed the Río Blanco intake directly, conserving them still contributes to caring for water across the territory. Protecting the forest and its water sources helps preserve the quality of the water flowing into creeks and other watercourses that in turn belong to the Guacaica and Chinchiná river basins. In this way, every protected forest adds to a wider network of water and life.'::text), true) where id = 'agua' and coalesce(scripts #>> '{punto_mrji6sqk774,en}', '') = '';
update public.routes set scripts = jsonb_set(scripts, '{punto_mrjik48w753,en}', to_jsonb('It is worth watching how the water, along its course, meets different features of the terrain and shapes waterfalls of different kinds.'::text), true) where id = 'agua' and coalesce(scripts #>> '{punto_mrjik48w753,en}', '') = '';
update public.routes set scripts = jsonb_set(scripts, '{punto_mrjjstue537,en}', to_jsonb('This is the last waterfall on our walk. We believe there are others further downstream, but the terrain makes them hard to reach.

We hope this path through Cantares has helped you understand a little better how water moves, is captured, is held and flows in the montane forest, and the close relationship between the springs, the vegetation, the soil and the different forms of life that inhabit this ecosystem.

To care for the forest is also to care for the water. Thank you for walking it with us, for your interest, and for being part of this purpose of conservation.'::text), true) where id = 'agua' and coalesce(scripts #>> '{punto_mrjjstue537,en}', '') = '';
update public.routes set scripts = jsonb_set(scripts, '{punto_mrkr2rpg423,en}', to_jsonb('At this first stop we see the spring that supplies water to the house and the cabin. Even through the harshest dry spells it has kept its flow. We hope that, with care and conservation of its surroundings, it will go on flowing this way for many years to come.'::text), true) where id = 'agua' and coalesce(scripts #>> '{punto_mrkr2rpg423,en}', '') = '';
update public.routes set scripts = jsonb_set(scripts, '{punto_mrksn238642,en}', to_jsonb('This spring was found recently by Reynaldo, the forest keeper at Cantares. Finding a new spring is always cause for joy: its presence speaks of the forest''s capacity to capture, hold and circulate water, and is a sign of how alive this ecosystem is.'::text), true) where id = 'agua' and coalesce(scripts #>> '{punto_mrksn238642,en}', '') = '';
update public.routes set scripts = jsonb_set(scripts, '{punto_mrksr7qd677,en}', to_jsonb('Springs face a range of threats: deforestation; extensive cattle ranching, which thins and degrades the vegetation that protects them; and climate phenomena such as El Niño, which can reduce rainfall and affect their flow. The ecological restoration we have undertaken at Cantares aims to recover and protect the plant cover and, with it, to help conserve these springs and the water that sustains life in the Reserve.'::text), true) where id = 'agua' and coalesce(scripts #>> '{punto_mrksr7qd677,en}', '') = '';
update public.routes set scripts = jsonb_set(scripts, '{punto_mrm9equb640,en}', to_jsonb('Bromeliads are small ecosystems in their own right, contributing to the water cycle and to the forest''s biodiversity. Their leaves grow in a rosette that works as a small natural reservoir, collecting rainwater and moisture from the mist. Through its leaves the plant draws on this water and the nutrients it carries. At the same time, the stored water creates a small habitat for insects and other organisms, making every bromeliad a tiny reservoir of water and of life.'::text), true) where id = 'agua' and coalesce(scripts #>> '{punto_mrm9equb640,en}', '') = '';
update public.routes set scripts = jsonb_set(scripts, '{punto_1,en}', to_jsonb('Orchids of the genera Cyrtochilum, Epidendrum and Masdevallia, epiphytic bromeliads that serve as nurseries for tadpoles, and the black anthurium, the emblematic flower of Manizales.'::text), true) where id = 'flora' and coalesce(scripts #>> '{punto_1,en}', '') = '';
