update public.waypoints set description_en = 'Tree up to 8 m tall, with a short, twisted, greyish trunk; its branches are pubescent and lenticellate and begin to grow low down on the trunk. Leaves simple, alternate, arranged helically, acuminate, lanceolate and serrate, on short grooved axes, leathery, densely pubescent beneath and with numerous yellow glands on the upper surface. Inflorescences in axillary catkins, unisexual or bisexual, erect. Male flowers with 3–4 bracts and pistillate ones with 5–6, reddish-brown, dotted and densely clustered. The fruits are spherical drupes, brown when ripe, pubescent, with a waxy, fragrant whitish coating, each holding a single spherical seed whose testa is hard, rough-surfaced and dull. Habitat: regenerating pasture; very humid premontane forest (bmh-PM) – (bmh-MB) – (bh-MB). Native, between 1,700 and 3,400 m in altitude. Uses: food, industrial, domestic, restoration.' where id = 'arbol_1417' and coalesce(description_en, '') = '';
update public.waypoints set title_en = 'Cedro Riñón' where id = 'arbol_1425' and coalesce(title_en, '') = '';
update public.waypoints set description_en = 'Tree native to the Cantares forest, family Brunelliaceae.' where id = 'arbol_1425' and coalesce(description_en, '') = '';
update public.waypoints set title_en = 'Dulumuco (Saurauia)' where id = 'arbol_1429' and coalesce(title_en, '') = '';
update public.waypoints set description_en = 'Tree native to the Cantares forest, family Actinidiaceae.' where id = 'arbol_1429' and coalesce(description_en, '') = '';
update public.waypoints set title_en = 'Chachafruto (Andean Tree Bean)' where id = 'arbol_1430' and coalesce(title_en, '') = '';
update public.waypoints set description_en = 'Tree up to 15 m tall and 60 cm in trunk diameter, bearing short prickles. Leaves compound, alternate, trifoliate and triangular in outline, with free stipules at the base of the petiole, arranged helically, pointed at the tip and glabrous; the margin is entire and the texture leathery. Flowers zygomorphic, made up of four red-orange petals, the androecium set within the keel with nine stamens forming one group and a further separate one; together the flowers form a dense conical raceme. The fruit is a legume, distinctive for the constriction at each seed, pendulous, each pod holding several reddish-brown, kidney-shaped seeds whose cotyledons are fleshy. Habitat: planted; very humid premontane forest (bmh-PM) and very humid lower montane forest (bmh-MB). Native, between 1,300 and 2,800 m in altitude. Uses: food, ornamental, domestic, restoration, soil recovery.' where id = 'arbol_1430' and coalesce(description_en, '') = '';
update public.waypoints set title_en = 'Encenillo (Weinmannia)' where id = 'arbol_1433' and coalesce(title_en, '') = '';
update public.waypoints set description_en = 'The tree reaches up to 20 m in height and 60 cm in trunk diameter, with grooved grey bark; its branches are a reddish green. The leaves are opposite, decussate, compound and imparipinnate, with serrate, pubescent leaflets, a rachis bearing leafy projections, pink or maroon, and interpetiolar stipules that are rolled and deciduous. Inflorescences in long, dense, pubescent racemes. Flowers small; calyx with four reduced, triangular, pubescent sepals; corolla with four cream-yellow petals and numerous exserted stamens. Fruit a bilocular, septicidal, brown capsule with a persistent style and small seeds. Habitat: regenerating pasture; very humid lower montane forest (bmh-MB). Native, between 2,000 and 3,000 m in altitude. Uses: ornamental, domestic.' where id = 'arbol_1433' and coalesce(description_en, '') = '';
update public.waypoints set title_en = 'Mano de Oso (Oreopanax)' where id = 'arbol_1436' and coalesce(title_en, '') = '';
update public.waypoints set description_en = 'Tree reaching 25 m in height and 40 cm in diameter, with a straight trunk and greyish-brown bark that is slightly scaly and cracked; its crown is umbrella-shaped. The leaves are simple and alternate, arranged helically and in terminal clusters, with serrate lobes along the margin recalling the palm of a hand, glabrous, on petioles of varying length, with reddish bracts protecting the young leaves. The flowers are very numerous, cream-coloured and inconspicuous, gathered into heads on dense terminal panicles. The fruits are glossy subglobose drupes, brown to purplish, turning reddish as they ripen, each holding four or five hard seeds with two flattened faces and one curved, yellow in colour. Habitat: forest; very humid lower montane forest (bmh-MB) – humid lower montane forest (bh-MB) – (bs-MB). Native, between 2,000 and 2,900 m in altitude. Uses: food, industrial, ornamental, domestic, restoration.' where id = 'arbol_1436' and coalesce(description_en, '') = '';
update public.waypoints set title_en = 'Cedro Negro' where id = 'arbol_1456' and coalesce(title_en, '') = '';
update public.waypoints set description_en = 'Tree up to 30 m tall and 1 m or more in diameter, with thick greyish bark marked by very characteristic longitudinal fissures; leaves up to 70 cm long, with alternate to sub-opposite pinnae, serrate margins, unequal base and acuminate apex, ovate or oblong-ovate and hairy; male flowers in pendulous catkins 10–15 cm long, with green or yellowish-green bracts and flowers, the female ones in short few-flowered spikes. As flowering approaches the trees shed their foliage completely — an event that happens once a year and yields abundant, slow-germinating fruit. The fruits are globose drupes up to 7 cm across, covered in a light brown indumentum, with a fleshy exocarp and a hard, woody, longitudinally grooved endocarp. Habitat: planted; very humid premontane forest (bmh-PM) – (bmh-MB) – (bh-MB). Native, between 1,700 and 2,800 m in altitude. Uses: industrial, craft, food, medicinal, domestic, ornamental.' where id = 'arbol_1456' and coalesce(description_en, '') = '';
